import { z } from 'zod';

export const UserPayloadSchema = z.object({
  userId: z.string().uuid(),
  email: z.string().email(),
  role: z.enum(['admin', 'editor', 'student']),
  isActive: z.boolean().default(true)
});

export type UserPayload = z.infer<typeof UserPayloadSchema>;

export interface ApiResponse<T> {
  success: boolean;
  data: T;
  error?: string;
  timestamp: number;
}

export async function fetchWithRetry<T>(url: string, retries = 3): Promise<ApiResponse<T>> {
  for (let i = 0; i < retries; i++) {
    try {
      const res = await fetch(url, { headers: { 'Accept': 'application/json' } });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const data = await res.json();
      return { success: true, data, timestamp: Date.now() };
    } catch (err) {
      if (i === retries - 1) return { success: false, data: null as any, error: (err as Error).message, timestamp: Date.now() };
      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
    }
  }
  throw new Error('Unreachable');
}

import React, { useTransition, useState } from 'react';

export function AsyncDataViewer({ initialCount }: { initialCount: number }) {
  const [isPending, startTransition] = useTransition();
  const [count, setCount] = useState(initialCount);

  const handleUpdate = () => {
    startTransition(() => {
      setCount(prev => prev + 1);
    });
  };

  return (
    <div className='p-4 border rounded shadow-sm'>
      <p>Processed Items: {count} {isPending && '<span>(Updating...)</span>'}</p>
      <button onClick={handleUpdate} className='px-4 py-2 bg-cyan-600 text-white rounded'>Execute</button>
    </div>
  );
}

